INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·巻四百八十", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/521cc8b13f7fb2df02cb842716b80438a03573b1/content/books/zizhi-tongjian/vol-292/year-0956/part-04/sources/library/songshi-480-wuyue-956-dispatch/source.txt", "note": "《宋史》巻四百八十，段落 songshi-9c6e46fee832-p075027；EPUB电子本，纸本及异文待核", "id": "bf0b446b-5d64-588a-b640-3236a581951b"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/521cc8b13f7fb2df02cb842716b80438a03573b1/content/books/zizhi-tongjian/vol-292/year-0956/part-04/sources/library/tongjian-292-956-pan-zhou-conclusion/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003474；电子底本待考，分段待核", "id": "15e2971e-3557-5da6-b03c-8fde02cddbb8"}, {"title": "新五代史·卷六十六", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/521cc8b13f7fb2df02cb842716b80438a03573b1/content/books/zizhi-tongjian/vol-292/year-0956/part-04/sources/library/xinwudaishi-66-wangkui-pan-death/source.txt", "note": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003338；EPUB电子本，纸本及异文待核", "id": "760ae1a7-43f3-57a0-ba5a-2ab9cff55295"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5b7d39c10017d28c66750d6a92a9b6db748131ef/content/books/zizhi-tongjian/vol-292/year-0956/part-03/sources/library/tongjian-292-956-yangzhou-diplomacy/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003473；电子底本待考，分段待核", "id": "31a2e238-3147-5ada-a694-fdcdef0dcf25"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3cf04308010988e93f2be2b3123fa7653105db77/content/books/zizhi-tongjian/vol-292/year-0956/part-02/sources/library/jiuwudaishi-116-february-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002747；EPUB电子本，纸本及异文待核", "id": "5cb34744-9920-5ee5-acd6-d4771ea25ea7"}, {"title": "新五代史·卷六十六", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cd645e3efcb32aa415b690b609c4d750baa3dbf6/content/books/zizhi-tongjian/vol-292/year-0954/part-04/sources/library/xinwudaishi-66-zhou-xingfeng-954/source.txt", "note": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003341；EPUB电子本，纸本及异文待核", "id": "14341213-87bf-507f-9c44-092854e31aea"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "尹延范", "aliases": ["尹延範"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐园苑使。956年奉李璟命到泰州，将吴让皇杨溥的族人迁至润州；因路途困难且担忧杨氏生变，杀死该族六十名男子，返报后被李璟处死。生年未载。", "biography": null, "status": "draft", "id": "acd6930a-f34b-531b-9435-cc9775878ae6"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "方讷", "aliases": ["方訥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐泰州刺史。956年二月后周韩令坤攻取泰州时，逃往金陵。生卒年未载。", "biography": null, "status": "draft", "id": "4a8fd07b-6737-5a25-afff-bac4877d55e2"}, {"name": "何继先", "aliases": ["何繼先"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周静安军使。956年二月壬辰截获南唐以蜡丸传送的求救信息，并献送朝廷。生卒年未载。", "biography": null, "status": "draft", "id": "1ddc7b5c-4b1d-5222-823d-b22d738bb8d6"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "高防", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "昭义节度判官。947年张从恩拟往契丹朝见时，他以晋室亲属应守臣节为由劝谏，未被听从；张离镇后留下他协助赵行迁、王守恩。生卒年未载。", "biography": null, "status": "draft", "id": "603ffd47-a5a9-5c5a-90e1-fdc9ea0bc620"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "路彦铢", "aliases": ["路彥銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越上直都指挥使。956年二月癸巳奉钱弘俶命进攻南唐宣州。生卒年未载。", "biography": null, "status": "draft", "id": "3af8f6aa-3cc5-5dc1-ad7c-665a3e802e03"}, {"name": "罗晟", "aliases": ["羅晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越中直都指挥使。956年二月钱弘俶派吴程督鲍修让、罗晟赴常州。生卒年未载。", "biography": null, "status": "draft", "id": "19e44dec-b085-579c-821d-0087cde81018"}, {"name": "姚彦洪", "aliases": ["姚彥洪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐静海制置使。956年二月率兵民万人投奔吴越。生卒年未载。", "biography": null, "status": "draft", "id": "98910ac3-db64-5179-84f3-8ee8c68e5601"}, {"name": "潘叔嗣", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其果敢，与周行逢、张文表交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "0aa70d0f-a11c-50f9-a0e8-3e0a7278f26d"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "李简（岳州团练判官）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "岳州团练判官。956年潘叔嗣杀王逵后，派他率朗州将吏迎接潭州的周行逢。《新五代史》称其为潘叔嗣客将。与早年其他同名李简缺少同人证据，分档保存。", "biography": null, "status": "draft", "id": "29aaa4bd-0af9-53b0-a602-1f79289301dc"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "莫弘万", "aliases": ["莫弘萬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖南衡州刺史。956年周行逢进入朗州、接管武平武安事务时，命其暂掌潭州。生卒年未载。", "biography": null, "status": "draft", "id": "9a0d368e-2d87-5f8b-8c17-c1501ebb979e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李璟派尹延范将杨溥族人从泰州迁往润州", "start_year": 956, "end_year": 956, "time_original": "956年二月泰州战事期间，具体派遣日未载", "dynasty": "五代十国", "description": "李璟派尹延范将杨溥族人从泰州迁往润州。", "phases": [], "location_name": "泰州至润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b57efb43-626b-57b9-b0a1-dc2aa8ddf017"}, {"title": "尹延范在迁徙途中杀死六十名杨氏男子", "start_year": 956, "end_year": 956, "time_original": "956年二月迁族途中，具体杀害日未载", "dynasty": "五代十国", "description": "《通鉴》记尹延范因道路艰难，担心杨氏族人发生变乱，杀死该族六十名男子，之后返报。六十名男子是原书明确范围，不能改成全部男女族人被杀；生变是他的担忧，未证明被害者实际发动叛乱。", "phases": [], "location_name": "泰州至润州途中，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cf34dbd6-13f2-56eb-9e5b-a64acf533177"}, {"title": "李璟得知杀害杨氏男子后，处死尹延范", "start_year": 956, "end_year": 956, "time_original": "956年二月迁族返报后，具体处死日未载", "dynasty": "五代十国", "description": "李璟得知杀害杨氏男子后，处死尹延范。", "phases": [], "location_name": "南唐朝廷，具体行刑地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "73039f4c-b86b-5fd3-9770-78d1afd6e172"}, {"title": "韩令坤攻取泰州，方讷逃往金陵", "start_year": 956, "end_year": 956, "time_original": "956年二月辛卯报泰州归降前后，《资治通鉴》未单列夺城日", "dynasty": "五代十国", "description": "韩令坤攻取泰州，方讷逃往金陵。", "phases": [], "location_name": "泰州至金陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c9423beb-b6d1-59aa-854f-252ecdadd7f4"}, {"title": "李璟派人以蜡丸传信向契丹求援", "start_year": 956, "end_year": 956, "time_original": "956年二月壬辰截获以前，具体送信日未载", "dynasty": "五代十国", "description": "李璟派人以蜡丸传信向契丹求援。", "phases": [], "location_name": "南唐至契丹", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "79a03e49-4393-56b2-a29f-88ebb1e7ab43"}, {"title": "何继先截获南唐求援蜡丸并献送", "start_year": 956, "end_year": 956, "time_original": "956年二月壬辰", "dynasty": "五代十国", "description": "何继先截获南唐求援蜡丸并献送。", "phases": [], "location_name": "静安军相关截获地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "46a036aa-8ec8-5549-a71a-14d70b926778"}, {"title": "柴荣命高防暂掌泰州", "start_year": 956, "end_year": 956, "time_original": "956年二月泰州攻取后，具体任命日未单列", "dynasty": "五代十国", "description": "柴荣命高防暂掌泰州。", "phases": [], "location_name": "泰州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "16fb5845-f2e7-571a-8cdb-d37eb03b2eb0"}, {"title": "钱弘俶派路彦铢攻宣州，罗晟率战舰屯江阴", "start_year": 956, "end_year": 956, "time_original": "956年二月癸巳", "dynasty": "五代十国", "description": "钱弘俶派路彦铢攻宣州，罗晟率战舰屯江阴。", "phases": [], "location_name": "宣州及江阴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "af2975c9-0344-5ff6-8dd8-e34888f6b597"}, {"title": "姚彦洪率一万兵民投奔吴越", "start_year": 956, "end_year": 956, "time_original": "956年二月吴越分路进兵时，具体投奔日未单列", "dynasty": "五代十国", "description": "姚彦洪率一万兵民投奔吴越。", "phases": [], "location_name": "南唐至吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a93dec04-60eb-5c6d-83fa-357b1dd11ea7"}, {"title": "潘叔嗣称王逵将因谗言杀他，问将士是否愿一同西行", "start_year": 956, "end_year": 956, "time_original": "956年二月王逵出征时，具体讲话日未载", "dynasty": "五代十国", "description": "潘叔嗣告诉将士，自己侍奉王逵已尽力，但王逵信谗生疑，回军后可能杀他，因此不愿坐等死亡，询问将士是否愿一同西行。这是潘叔嗣的判断和动员说辞，不把王逵当时已下杀令写成确定事实。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dd04e5b6-e428-58bb-bf3e-a550c30b2af1"}, {"title": "将士同意西行，潘叔嗣率军袭击朗州", "start_year": 956, "end_year": 956, "time_original": "956年二月西行动员之后，具体进兵日未载", "dynasty": "五代十国", "description": "将士同意西行，潘叔嗣率军袭击朗州。", "phases": [], "location_name": "岳州至朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8686ccd3-ce82-589e-9042-6236716d02a3"}, {"title": "王逵回军追击潘叔嗣，在武陵城外战败被杀", "start_year": 956, "end_year": 956, "time_original": "956年二月潘叔嗣袭朗州之后，具体战日未载", "dynasty": "五代十国", "description": "王逵回军追击潘叔嗣，在武陵城外战败被杀。", "phases": [], "location_name": "武陵城外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "46d8e2b8-3384-5828-97a4-115f563f83e8"}, {"title": "潘叔嗣拒绝占据朗州，表示愿迎周行逢并期待获授武安", "start_year": 956, "end_year": 956, "time_original": "956年武陵交战之后", "dynasty": "五代十国", "description": "潘叔嗣拒绝占据朗州，表示愿迎周行逢并期待获授武安。", "phases": [], "location_name": "朗州及武陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2ddcd78e-a3a1-5491-aa66-9d69dfa5dc3e"}, {"title": "潘叔嗣返回岳州，派李简率朗州将吏迎周行逢", "start_year": 956, "end_year": 956, "time_original": "956年武陵交战之后，具体迎接日未载", "dynasty": "五代十国", "description": "潘叔嗣返回岳州，派李简率朗州将吏迎周行逢。", "phases": [], "location_name": "岳州、朗州至潭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a4398704-4fb6-586d-b6f6-0f53b72b6c9e"}, {"title": "周行逢担心被视为与潘叔嗣同谋，打算先授行军司马", "start_year": 956, "end_year": 956, "time_original": "956年受迎接之后，具体讲话日未载", "dynasty": "五代十国", "description": "有人建议把潭州给潘叔嗣，周行逢称潘杀主帅应受重罚，但因他迎接自己而暂缓；若立即授节度使，恐被外界看成共同谋杀王逵。因此主张先任行军司马，等跨年后再考虑节度。此处跨年是计划，不表示后来真正等了一年。", "phases": [], "location_name": "潭州至朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "765512e6-91e1-5d98-9f88-dc4e0ba8ba14"}, {"title": "周行逢命衡州刺史莫弘万暂掌潭州", "start_year": 956, "end_year": 956, "time_original": "956年周行逢转赴朗州时，具体日未载", "dynasty": "五代十国", "description": "周行逢命衡州刺史莫弘万暂掌潭州。", "phases": [], "location_name": "潭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "516a8c31-37ba-56f0-bff3-b749bf45c40d"}, {"title": "周行逢入朗州，自称武平、武安留后并告知朝廷", "start_year": 956, "end_year": 956, "time_original": "956年迎入朗州之后，具体日未载", "dynasty": "五代十国", "description": "周行逢入朗州，自称武平、武安留后并告知朝廷。", "phases": [], "location_name": "朗州及后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9a2651f4-52b4-59a5-92bd-b84c19f3cb8c"}, {"title": "周行逢任潘叔嗣为行军司马，潘叔嗣称病不来", "start_year": 956, "end_year": 956, "time_original": "956年周行逢接管朗州以后", "dynasty": "五代十国", "description": "周行逢任潘叔嗣为行军司马，潘叔嗣称病不来。", "phases": [], "location_name": "朗州至岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6138fc4b-697e-53a7-b23e-6fe71fedf1e4"}, {"title": "周行逢认为潘叔嗣拒绝任命是不满，并怀疑他要谋害自己", "start_year": 956, "end_year": 956, "time_original": "956年潘叔嗣称病不至后", "dynasty": "五代十国", "description": "周行逢认为潘叔嗣拒绝任命是不满，并怀疑他要谋害自己。", "phases": [], "location_name": "朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "30db6ccd-186d-5861-ab69-446855032eac"}, {"title": "周行逢采纳他人建议，以授武安节度使诱潘叔嗣到府", "start_year": 956, "end_year": 956, "time_original": "956年拒任争议之后，具体日未载", "dynasty": "五代十国", "description": "周行逢采纳他人建议，以授武安节度使诱潘叔嗣到府。", "phases": [], "location_name": "朗州至岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b809ae9c-c774-5ed8-a977-c7d69ef3b0e7"}, {"title": "近人劝潘叔嗣不要前往，潘因素来亲善而不疑赴约", "start_year": 956, "end_year": 956, "time_original": "周行逢诱召之后，具体出发日未载", "dynasty": "五代十国", "description": "近人劝潘叔嗣不要前往，潘因素来亲善而不疑赴约。", "phases": [], "location_name": "岳州至朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3de13e78-acb0-59df-9041-9adbbc4c3af2"}, {"title": "周行逢沿路遣使迎候潘叔嗣，到府后亲自慰劳", "start_year": 956, "end_year": 956, "time_original": "潘叔嗣赴约到达时，具体日未载", "dynasty": "五代十国", "description": "周行逢沿路遣使迎候潘叔嗣，到府后亲自慰劳。", "phases": [], "location_name": "赴朗州道路及府中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "27ef54ee-b9b6-5024-b0fa-73f6b50b6e99"}, {"title": "周行逢拘押来谒的潘叔嗣，责其杀主帅并拒命", "start_year": 956, "end_year": 956, "time_original": "赴府受迎接之后，具体日未载", "dynasty": "五代十国", "description": "潘叔嗣入谒未到厅堂就被拘押，周行逢责他无大功却杀王逵，又说自己因旧交暂不杀、只任行军司马，而潘拒绝任命。责问属于周行逢的辩解，不将无功等评价当成独立已证结论。", "phases": [], "location_name": "朗州府庭", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b2a771c2-4be0-52c2-b5d7-de48f8109dfa"}, {"title": "潘叔嗣请求顾全宗族，随后被周行逢处死", "start_year": null, "end_year": null, "time_original": "956年王逵死后、诱召赴府之后，具体死亡年日未另载", "dynasty": "五代十国", "description": "潘叔嗣请求顾全宗族，随后被周行逢处死。", "phases": [], "location_name": "朗州府中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8b2fcf40-0a60-5406-88ca-3d31aa46e832"}]'::jsonb)
